const url = ($json.websiteUrl || '')                                                                                                                                
    .replace(/^https?:\/\//, '')                                                                                                                                    
    .replace(/^www\./, '')                                                                                                                                            
    .split('/')[0]
    .split('?')[0]                                                                                                                                                    
    .trim();                                                                                                                                                        

return {
json: {                                                                                                                                                           
    ...$json,                                                                                                                                                     
    domain: url
}
};

const domain = ($json.domain || '').trim();
const email = domain ? `info@${domain}` : null;

return {
json: {
    businessName: $json.businessName,
    websiteUrl: $json.websiteUrl,
    location: $json.location,
    phoneNumber: $json.phoneNumber ?? null,
    source: $json.source,
    email,
    emailSource: email ? 'pattern' : null
}
};

return $input.all().map(item => ({
  json: {
    businessName: item.json.businessName,
    websiteUrl: item.json.websiteUrl,
    location: item.json.location,
    phoneNumber: item.json.phoneNumber ?? null,
    source: item.json.source,
    email: item.json.email,
    emailSource: item.json.emailSource
  }
}));

const blockedDomains = new Set([
  'instagram.com',
  'www.instagram.com',
  'facebook.com',
  'www.facebook.com',
  'fb.com',
  'www.fb.com',
  'twitter.com',
  'www.twitter.com',
  'x.com',
  'www.x.com',
  'linkedin.com',
  'www.linkedin.com',
  'youtube.com',
  'www.youtube.com',
  'tiktok.com',
  'www.tiktok.com'
]);

return $input.all().filter(item => {
  const domain = String(item.json.domain || '').toLowerCase().trim();
  return domain && !blockedDomains.has(domain);
});
